window.blogDetail = {"blogId":1510328080,"blogType":0,"pubTime":"2017-11-10 23:34","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"我读红楼梦（25）第21回 贤袭人娇嗔箴宝玉，俏平儿软语救贾琏——贾宝玉的孩童心理剖析","commentNum":0,"effect1":1024,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"第21回的回目中提及了两个人：袭人和平儿，并在前面各自加了“贤”和“俏”两个字。看起来是写两个丫鬟，其实是通过两个丫鬟的名字来映射宝玉和凤姐。贤袭人娇嗔箴宝玉，箴的是宝玉始终沉溺在童年般的幼稚之中，永远不想长大。俏平儿软语救贾琏其实救的是贾琏永远无法摆脱的性欲的罪恶。作者把这两个人放在同一回，其实就是想通过情与性的对比，告诉我们，其实每个人在人世间都有属于自己的执迷，如果没有等到恰当的时机，是永远...","artype":1,"arUins":"","blogid":1510328080,"voteids":0,"pubtime":1510328080,"replynum":0,"category":"个人日记","effect":1024,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1510328080,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"我读红楼梦（25）第21回 贤袭人娇嗔箴宝玉，俏平儿软语救贾琏——贾宝玉的孩童心理剖析","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1510328080"}